draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw mirror
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.rect(W/2 - 50, H/2 - 100, 100, 200);
  ctx.stroke();

  // draw stick figure
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 - 20, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 + 20, H/2 + 40);
  ctx.stroke();

  // draw distorted reflection
  ctx.save();
  ctx.translate(W/2, H/2);
  ctx.scale(1 + 0.2 * Math.sin(t), 1 - 0.2 * Math.sin(t));
  ctx.beginPath();
  ctx.arc(0, 0, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(0, 20);
  ctx.lineTo(0, 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(0, 30);
  ctx.lineTo(-20, 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(0, 30);
  ctx.lineTo(20, 40);
  ctx.stroke();
  ctx.restore();

  ctx.restore();
}
